 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff020b17);getWindow().setNavigationBarColor(0xff020b17);art=new AccessView();setContentView(art);if(getIntent().getBooleanExtra("unlocked",false)){status="IDENTITY VERIFIED";art.postDelayed(()->success(),220);}}
 void authenticate(boolean credential){if(granted||getIntent().getBooleanExtra("unlocked",false))return;KeyguardManager keyguard=getSystemService(KeyguardManager.class);if(!keyguard.isDeviceSecure()){status="SET A DEVICE LOCK IN ANDROID SETTINGS";art.invalidate();return;}if(credential||Build.VERSION.SDK_INT<28){Intent i=keyguard.createConfirmDeviceCredentialIntent("Orbit Access","Confirm with your device screen lock");if(i!=null)startActivityForResult(i,81);return;}cancellation=new CancellationSignal();BiometricPrompt.Builder b=new BiometricPrompt.Builder(this).setTitle("Orbit Access").setSubtitle("Authenticate to preview the unlock transition");if(Build.VERSION.SDK_INT>=30)b.setAllowedAuthenticators(BiometricManager.Authenticators.BIOMETRIC_STRONG|BiometricManager.Authenticators.DEVICE_CREDENTIAL);else if(Build.VERSION.SDK_INT>=29)b.setDeviceCredentialAllowed(true);else b.setNegativeButton("Device code",getMainExecutor(),(d,w)->authenticate(true));b.build().authenticate(cancellation,getMainExecutor(),new BiometricPrompt.AuthenticationCallback(){public void onAuthenticationSucceeded(BiometricPrompt.AuthenticationResult r){success();}public void onAuthenticationFailed(){status="NOT RECOGNIZED · TRY AGAIN";}public void onAuthenticationError(int code,CharSequence error){status="READY TO SCAN";art.invalidate();}});}
